import app from 'flarum/common/app';
const base = () => app.forum.attribute('apiUrl');
export function testConnection(source, config) {
  return app.request({
    method: 'POST',
    url: `${base()}/importer/test`,
    body: {
      source,
      config
    }
  });
}

/** Upload a database dump (.sql/.sql.gz) or SQLite file; returns row counts + a handle for start(). */
export function uploadDump(source, prefix, file) {
  const fd = new FormData();
  fd.append('source', source);
  fd.append('prefix', prefix);
  fd.append('file', file);
  return fetch(`${base()}/importer/upload`, {
    method: 'POST',
    headers: {
      'X-CSRF-Token': app.session.csrfToken
    },
    credentials: 'same-origin',
    body: fd
  }).then(r => r.json());
}
export function startImport(source, config) {
  return app.request({
    method: 'POST',
    url: `${base()}/importer/start`,
    body: {
      source,
      config
    }
  });
}

/** Process one bounded batch of a running import. */
export function stepImport(runId) {
  return app.request({
    method: 'POST',
    url: `${base()}/importer/step`,
    body: {
      runId
    }
  });
}
export function importStatus(runId) {
  const q = runId ? `?runId=${runId}` : '';
  return app.request({
    method: 'GET',
    url: `${base()}/importer/status${q}`
  });
}
export function resetImport(runId) {
  return app.request({
    method: 'POST',
    url: `${base()}/importer/reset`,
    body: runId ? {
      runId
    } : {}
  });
}
/** What redirects would do, before anybody turns them on. */
export function redirectState(runId, source) {
  const q = [];
  if (runId) q.push(`runId=${runId}`);
  if (source) q.push(`source=${encodeURIComponent(source)}`);
  return app.request({
    method: 'GET',
    url: `${base()}/importer/redirects${q.length ? '?' + q.join('&') : ''}`
  });
}

/**
 * Turn redirects on for one run, or off.
 *
 * Rejects with a 422 carrying `reason` when the combination would resolve
 * nothing — an empty map, an unknown platform, a run that no longer exists.
 */
export function saveRedirects(enabled, runId, source) {
  return app.request({
    method: 'POST',
    url: `${base()}/importer/redirects`,
    body: {
      enabled,
      runId,
      source
    },
    errorHandler: e => {
      throw e;
    }
  });
}
flarum.reg.add('ernestdefoe-importer', 'common/api', { testConnection: testConnection,uploadDump: uploadDump,startImport: startImport,stepImport: stepImport,importStatus: importStatus,resetImport: resetImport,redirectState: redirectState,saveRedirects: saveRedirects, });